from fractions import Fraction
from typing import Tuple, Sequence

Statement = Tuple[bool, ...]

def payoff(s: Statement, b: bool, w: int) -> int:
    """+1 if the bet matches the truth value in world w, else -1."""
    return 1 if b == s[w] else -1

def expected_profit(s: Statement, b: bool) -> Fraction:
    """Expected profit of bet b under the uniform prior over worlds."""
    n = len(s)
    return Fraction(sum(payoff(s, b, w) for w in range(n)), n)

def opt_profit(s: Statement) -> Fraction:
    """Optimal expected profit: the better of the two bets."""
    return max(expected_profit(s, True), expected_profit(s, False))

def deck_opt_profit(deck: Sequence[Statement]) -> Fraction:
    """Average optimal profit across a deck of cards."""
    return sum((opt_profit(s) for s in deck), Fraction(0)) / len(deck)

# Demo: the game is zero-sum and decidable cards pay the maximum.
if __name__ == "__main__":
    valid    = (True, True, True, True)
    balanced = (True, True, False, False)
    unsat    = (False, False, False, False)
    for name, s in [("valid", valid), ("balanced", balanced), ("unsat", unsat)]:
        et, ef = expected_profit(s, True), expected_profit(s, False)
        print(f"{name:9s}  E[TRUE]={et!s:>5}  E[FALSE]={ef!s:>5}  sum={et+ef}")
    print("optimal profit valid   =", opt_profit(valid))     # 1
    print("optimal profit balanced=", opt_profit(balanced))  # 0

