import random

# Demo: simulate 1000 independent (undecidable) ZFC-style cards and show the
# player's edge is exactly 0 in expectation and -1 in the worst case.
def worst_case_profit(s: Statement, b: bool) -> int:
    return min(payoff(s, b, w) for w in range(len(s)))

if __name__ == "__main__":
    rng = random.Random(2024)
    deck = [((True, False) if rng.random() < 0.5 else (False, True))
            for _ in range(1000)]
    print("average optimal expected profit:", deck_opt_profit(deck))  # 0
    worst = sum(max(worst_case_profit(s, True), worst_case_profit(s, False))
                for s in deck)
    print("best worst-case total profit   :", worst)                  # -1000

