function OPTIMAL_BET_AND_PROFIT(s):
    n <- number of worlds in s
    t <- count of worlds where s is true
    e_true <- (2*t - n) / n
    if e_true >= 0:
        return (TRUE, e_true)
    else:
        return (FALSE, -e_true)

function DECK_EXPECTED_EDGE(deck):
    total <- 0
    for each statement s in deck:
        n <- number of worlds in s
        t <- count of true worlds in s
        total <- total + |(2*t - n)/n|
    return total / length(deck)

function CLASSIFY_AND_WORST_CASE(s):
    if s is true in every world:
        return ('valid', +1)
    if s is false in every world:
        return ('unsatisfiable', +1)
    return ('independent', -1)
